type CollectionListRow = { id: string; slug: string; name: string; description: string; privacy: "public" | "unlisted" | "private"; show_author: boolean; created_at: string; updated_at: string; _count: { modules: number }; owner: { telegram_id: string }; };
type UserCollection = { slug: string; name: string; description: string; privacy: string; _count: { modules: number }; };

function trimDescription(value: string): string { return value.length > 145 ? `${value.slice(0, 145).trim()}…` : value; }
function ModulePreview({ module, lang }: { module: ModuleCard; lang: "ru" | "en" }) {
  const router = useRouter();
  const [mlikes, setMlikes] = useState(module.likes);
  const [mdislikes, setMdislikes] = useState(module.dislikes);
  const [userVote, setUserVote] = useState<"like" | "dislike" | null>(null);
  const [voting, setVoting] = useState<"like" | "dislike" | null>(null);
  const [animating, setAnimating] = useState<"like" | "dislike" | null>(null);
  const [countBump, setCountBump] = useState<"like" | "dislike" | null>(null);
  const [countDecay, setCountDecay] = useState<"like" | "dislike" | null>(null);
  const [showAuth, setShowAuth] = useState(false);
  const srcHref = module.source_url;
  const desc = module.locales?.description_en || module.description || (lang === "en" ? "Description is not added yet." : "Описание пока не добавлено.");
  const displayDesc = lang === "ru" ? (module.description || desc) : desc;
   async function vote(action: "like" | "dislike", e: React.MouseEvent) {
    const oldVote = userVote;
    e.stopPropagation(); setVoting(action); setAnimating(action);
    const r = await fetch(`/api/web/rate/${encodeURIComponent(module.source_owner)}/${encodeURIComponent(module.name)}/${action}`, { method: "POST" });
    setVoting(null);
    if (r.status === 401) { setShowAuth(true); setAnimating(null); return; }
    if (r.ok) {
      const d = (await r.json()) as { summary: { likes: number; dislikes: number; userAction: "like" | "dislike" | null } };
      const newVote = d.summary.userAction;
      if (oldVote && oldVote !== newVote) {
        setCountDecay(oldVote);
        setTimeout(() => {
          setMlikes(d.summary.likes); setMdislikes(d.summary.dislikes); setUserVote(newVote);
          setCountBump(newVote!); setCountDecay(null);
          setTimeout(() => { setAnimating(null); setCountBump(null); }, 400);
        }, 350);
        setTimeout(() => setAnimating(null), 500);
      } else {
        setMlikes(d.summary.likes); setMdislikes(d.summary.dislikes); setUserVote(newVote);
        if (newVote === action) setCountBump(action);
        setTimeout(() => { setAnimating(null); setCountBump(null); }, 500);
      }
    }
  }
  function goCard(e: React.MouseEvent) { if ((e.target as HTMLElement).closest("a,button")) return;  router.prefetch(srcHref); router.push(srcHref); }
  return <><article className="module-card" onMouseEnter={() => router.prefetch(srcHref)} onFocus={() => router.prefetch(srcHref)} onMouseDown={(e) => { if (!(e.target as HTMLElement).closest("a,button")) createRipple(e); }} onClick={goCard}><ModuleBanner src={module.banner} className="module-banner-card" /><span className="module-head"><strong>{module.name}</strong><em>v{module.version}</em></span><span className="module-class">{module.class_name}</span><p>{trimDescription(displayDesc)}</p>{module.tags?.length ? <span className="module-tags">{module.tags.map((t: string, i: number) => <TagLink key={t} tag={t} index={i} onClick={(event) => event.stopPropagation()} />)}</span> : null}<span className="module-meta"><Link href={`/developers/${encodeURIComponent(module.source_owner)}`} prefetch onClick={(e) => e.stopPropagation()}><b>{module.developer}{module.is_official_developer ? <OfficialBadge size={15} /> : null}</b></Link></span><span className="module-actions" onClick={e => e.stopPropagation()}><button className={"ma-vote" + (userVote === "like" ? " selected" : "") + (animating === "like" ? " vote-pop-like" : "")} onMouseDown={(e) => createRipple(e)} onClick={e => vote("like", e)} disabled={!!voting}><span className={animating === "like" ? "vote-pop" : ""}><LikeIcon /></span><b className={(countBump === "like" ? "count-bump " : "") + (countDecay === "like" ? "decay-snap" : "")}>{mlikes}</b></button><button className={"ma-vote ma-vote-d" + (userVote === "dislike" ? " selected" : "") + (animating === "dislike" ? " vote-pop-dislike" : "")} onMouseDown={(e) => createRipple(e)} onClick={e => vote("dislike", e)} disabled={!!voting}><span className={animating === "dislike" ? "vote-pop" : ""}><DislikeIcon /></span><b className={(countBump === "dislike" ? "count-bump " : "") + (countDecay === "dislike" ? "decay-snap" : "")}>{mdislikes}</b></button><a href={module.source_raw_url ?? module.source_url} rel="nofollow" target="_blank">Raw</a><a href={module.source_download_url ?? module.source_url} rel="nofollow">Download .py</a></span></article>{showAuth ? <AuthRequiredModal title={lang === "en" ? "Sign in with Telegram" : "Войдите через Telegram"} description={lang === "en" ? "Sign in to rate modules." : "Войдите, чтобы оценивать модули."} onClose={() => setShowAuth(false)} lang={lang} /> : null}</>;
}

