  useEffect(() => { const controller = new AbortController(); const q = query.trim(); if (!q) { if (searchHydrated) { setResults([]); try { sessionStorage.removeItem("vs_q"); sessionStorage.removeItem("vs_r"); } catch {} } setLoading(false); return; } try { const cachedQ = sessionStorage.getItem("vs_q"); const cachedR = sessionStorage.getItem("vs_r"); if (cachedQ === q && cachedR) { setResults(JSON.parse(cachedR)); setLoading(false); return; } } catch {} setLoading(true); const timer = window.setTimeout(async () => { try { const response = await fetch(`/api/search?q=${encodeURIComponent(q)}&limit=30`, { cache: "no-cache", signal: controller.signal }); if (response.ok) { const data = (await response.json()) as { results: ModuleCard[] }; setResults(data.results); try { sessionStorage.setItem("vs_q", q); sessionStorage.setItem("vs_r", JSON.stringify(data.results)); } catch {} } } catch (error) { if (!(error instanceof DOMException && error.name === "AbortError")) console.error(error); } finally { if (!controller.signal.aborted) setLoading(false); } }, 180); return () => { window.clearTimeout(timer); controller.abort(); }; }, [query, searchHydrated]);

